import React, { useEffect } from "react";
import { navigate, HeadFC } from "gatsby";
import Navbar from "../components/nav";
import Intro from "../components/intro";
import Footer from "../components/footer";
import SEO from "../components/seo";

const Home: React.FC = () => {
  useEffect(() => {
    if (typeof window !== "undefined") {
      const searchParams = new URLSearchParams(window.location.search);
      const path = searchParams.get('path');
      
      if (path) {
        searchParams.delete('path');
        const newSearch = searchParams.toString() ? `?${searchParams.toString()}` : '';
        navigate(path + newSearch, { replace: true });
      }
    }
  }, []);

  return (
    <>
    <title>Josh Scragg - Software Developer</title>
    <main className="container">
      <Navbar />
      <Intro />
      <Footer />
    </main>
    </>
  );
};

export const Head: HeadFC = () => (
  <SEO 
    title="Josh Scragg - Software Developer" 
    description="24-year-old graduate software developer from New Zealand specializing in data-driven applications and backend systems"
  />
);

export default Home;